import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build(arr):
    if not arr or arr[0] == 'n':
        return None
    root = T(int(arr[0]))
    q = deque([root])
    i = 1
    while q and i < len(arr):
        n = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            n.l = T(int(arr[i])); q.append(n.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            n.r = T(int(arr[i])); q.append(n.r)
        i += 1
    return root

def right_brute(root):
    if not root:
        return []
    q = deque([root])
    res = []
    while q:
        level = []
        for _ in range(len(q)):
            n = q.popleft()
            level.append(n.v)
            if n.l: q.append(n.l)
            if n.r: q.append(n.r)
        res.append(level[-1])
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    root = build(data[1:1 + n])
    print(' '.join(map(str, right_brute(root))))

