def right_dfs(root):
    res = []
    def dfs(node, depth):
        if not node:
            return
        if depth == len(res):
            res.append(node.v)
        dfs(node.r, depth + 1)
        dfs(node.l, depth + 1)
    dfs(root, 0)
    return res

